1	// systolic_mesh_s8: 8x16 output-stationary systolic array for int8 GEMM.
2	// Interface matches gemm_s8.v so existing testbenches work unchanged.
3	// Single-tile only (M<=8, N<=16, arbitrary K). Full tiling in S02.
4	module systolic_mesh_s8 #(
5	    parameter PM       = 8,
6	    parameter PN       = 16,
7	    parameter A_LEN    = 65536,
8	    parameter B_LEN    = 65536,
9	    parameter C_LEN    = 16384,
10	    parameter BIAS_LEN = 1024,
11	    parameter DIM_W    = 16
12	)(
13	    input                clk,
14	    input                rst_n,
15	    input                start,
16	    input  [DIM_W-1:0]   M_in,
17	    input  [DIM_W-1:0]   K_in,
18	    input  [DIM_W-1:0]   N_in,
19	    input                use_bias,
20	    output reg           done
21	);
22	
23	    // Testbench accesses these via DUT.a_buf etc. — names must match gemm_s8.v
24	    reg signed [7:0]  a_buf    [0:A_LEN-1];
25	    reg signed [7:0]  b_buf    [0:B_LEN-1];
26	    reg signed [31:0] bias_buf [0:BIAS_LEN-1];
27	    reg signed [31:0] c_buf    [0:C_LEN-1];
28	
29	    // FSM states
30	    localparam S_IDLE    = 2'd0;
31	    localparam S_COMPUTE = 2'd1;
32	    localparam S_DRAIN   = 2'd2;
33	    localparam S_DONE    = 2'd3;
34	
35	    reg [1:0]        state;
36	    reg [DIM_W-1:0]  cycle_cnt;
37	    reg [DIM_W-1:0]  K_reg, M_reg, N_reg;
38	    reg              use_bias_reg;
39	    reg [DIM_W-1:0]  drain_m, drain_n;
40	
41	    // Total compute cycles needed: K + PM + PN - 2 (wavefront fill + drain)
42	    wire [DIM_W-1:0] total_cycles = K_reg + PM[DIM_W-1:0] + PN[DIM_W-1:0] - 16'd2;
43	
44	    // PE control signals
45	    reg pe_en;
46	    reg pe_acc_clear;
47	
48	    // Flat 1D accumulator output array for reliable variable-index reads
49	    wire signed [31:0] pe_acc [0:PM*PN-1];
50	
51	    // Horizontal (activation) wires: a_wire[row][0] = left-edge input
52	    wire signed [7:0] a_wire [0:PM-1][0:PN];
53	    // Vertical (weight) wires: b_wire[0][col] = top-edge input
54	    wire signed [7:0] b_wire [0:PM][0:PN-1];
55	
56	    // --- PE grid ---
57	    genvar gi, gj;
58	    generate
59	        for (gi = 0; gi < PM; gi = gi + 1) begin : row
60	            for (gj = 0; gj < PN; gj = gj + 1) begin : col
61	                pe_s8 pe_inst (
62	                    .clk      (clk),
63	                    .rst_n    (rst_n),
64	                    .en       (pe_en),
65	                    .acc_clear(pe_acc_clear),
66	                    .a_in     (a_wire[gi][gj]),
67	                    .b_in     (b_wire[gi][gj]),
68	                    .a_out    (a_wire[gi][gj+1]),
69	                    .b_out    (b_wire[gi+1][gj]),
70	                    .acc      (pe_acc[gi*PN+gj])
71	                );
72	            end
73	        end
74	    endgenerate
75	
76	    // --- Left-edge feeding (skewed by row index) ---
77	    // Row m feeds A[m, t-m] at compute cycle t, valid when t >= m and t-m < K
78	    generate
79	        for (gi = 0; gi < PM; gi = gi + 1) begin : a_feed
80	            wire [DIM_W-1:0] a_offset = cycle_cnt - gi[DIM_W-1:0];
81	            wire [31:0]      a_addr   = gi[DIM_W-1:0] * K_reg + a_offset;
82	            wire             a_valid  = (state == S_COMPUTE) &&
83	                                        (cycle_cnt >= gi[DIM_W-1:0]) &&
84	                                        (a_offset < K_reg);
85	            assign a_wire[gi][0] = a_valid ? a_buf[a_addr[15:0]] : 8'sd0;
86	        end
87	    endgenerate
88	
89	    // --- Top-edge feeding (skewed by column index) ---
90	    // Col n feeds B[t-n, n] at compute cycle t, valid when t >= n and t-n < K
91	    generate
92	        for (gj = 0; gj < PN; gj = gj + 1) begin : b_feed
93	            wire [DIM_W-1:0] b_offset = cycle_cnt - gj[DIM_W-1:0];
94	            wire [31:0]      b_addr   = b_offset * N_reg + gj[DIM_W-1:0];
95	            wire             b_valid  = (state == S_COMPUTE) &&
96	                                        (cycle_cnt >= gj[DIM_W-1:0]) &&
97	                                        (b_offset < K_reg);
98	            assign b_wire[0][gj] = b_valid ? b_buf[b_addr[15:0]] : 8'sd0;
99	        end
100	    endgenerate
101	
102	    // --- FSM ---
103	    always @(posedge clk or negedge rst_n) begin
104	        if (!rst_n) begin
105	            state        <= S_IDLE;
106	            done         <= 1'b0;
107	            pe_en        <= 1'b0;
108	            pe_acc_clear <= 1'b0;
109	            cycle_cnt    <= {DIM_W{1'b0}};
110	            K_reg        <= {DIM_W{1'b0}};
111	            M_reg        <= {DIM_W{1'b0}};
112	            N_reg        <= {DIM_W{1'b0}};
113	            use_bias_reg <= 1'b0;
114	            drain_m      <= {DIM_W{1'b0}};
115	            drain_n      <= {DIM_W{1'b0}};
116	        end else begin
117	            case (state)
118	                S_IDLE: begin
119	                    done <= 1'b0;
120	                    if (start) begin
121	                        M_reg        <= M_in;
122	                        K_reg        <= K_in;
123	                        N_reg        <= N_in;
124	                        use_bias_reg <= use_bias;
125	                        cycle_cnt    <= {DIM_W{1'b0}};
126	                        pe_en        <= 1'b1;
127	                        pe_acc_clear <= 1'b1;
128	                        state        <= S_COMPUTE;
129	                    end
130	                end
131	
132	                S_COMPUTE: begin
133	                    if (cycle_cnt == {DIM_W{1'b0}})
134	                        pe_acc_clear <= 1'b0;
135	
136	                    if (cycle_cnt == total_cycles) begin
137	                        pe_en   <= 1'b0;
138	                        drain_m <= {DIM_W{1'b0}};
139	                        drain_n <= {DIM_W{1'b0}};
140	                        state   <= S_DRAIN;
141	                    end else begin
142	                        cycle_cnt <= cycle_cnt + 1'b1;
143	                    end
144	                end
145	
146	                S_DRAIN: begin
147	                    c_buf[drain_m * N_reg + drain_n] <=
148	                        pe_acc[drain_m[3:0]*PN + drain_n[4:0]] +
149	                        (use_bias_reg ? bias_buf[drain_m] : 32'sd0);
150	
151	                    if (drain_n == N_reg - 1'b1) begin
152	                        drain_n <= {DIM_W{1'b0}};
153	                        if (drain_m == M_reg - 1'b1)
154	                            state <= S_DONE;
155	                        else
156	                            drain_m <= drain_m + 1'b1;
157	                    end else begin
158	                        drain_n <= drain_n + 1'b1;
159	                    end
160	                end
161	
162	                S_DONE: begin
163	                    done  <= 1'b1;
164	                    state <= S_IDLE;
165	                end
166	
167	                default: state <= S_IDLE;
168	            endcase
169	        end
170	    end
171	
172	endmodule
173

1	// gemm_s8: int8 matrix multiply with optional int32 bias.
2	//   A is row-major M-by-K  (a_buf[m*K + k] = A[m,k])
3	//   B is row-major K-by-N  (b_buf[k*N + n] = B[k,n])
4	//   bias is length M       (broadcast across N)
5	//   C is row-major M-by-N  (c_buf[m*N + n] = sum_k A[m,k]*B[k,n] + bias[m])
6	//
7	// Behavioral one-MAC-per-cycle implementation. For AWN's largest layer
8	// (conv2 im2col: M=64, K=320, N=128) this is ~2.6M cycles per call;
9	// iverilog runs it in well under a minute.
10	
11	module gemm_s8 #(
12	    parameter A_LEN    = 65536,
13	    parameter B_LEN    = 65536,
14	    parameter C_LEN    = 16384,
15	    parameter BIAS_LEN = 1024,
16	    parameter DIM_W    = 16
17	)(
18	    input                   clk,
19	    input                   rst_n,
20	    input                   start,
21	    input  [DIM_W-1:0]      M_in,
22	    input  [DIM_W-1:0]      K_in,
23	    input  [DIM_W-1:0]      N_in,
24	    input                   use_bias,
25	    output reg              done
26	);
27	
28	reg signed [7:0]  a_buf    [0:A_LEN-1];
29	reg signed [7:0]  b_buf    [0:B_LEN-1];
30	reg signed [31:0] bias_buf [0:BIAS_LEN-1];
31	reg signed [31:0] c_buf    [0:C_LEN-1];
32	
33	reg [DIM_W-1:0]   m, n;
34	reg [DIM_W:0]     k;       // one extra bit so k can equal K_in to terminate
35	reg signed [31:0] acc;
36	
37	reg [2:0] state;
38	localparam S_IDLE  = 3'd0;
39	localparam S_INIT  = 3'd1;
40	localparam S_MAC   = 3'd2;
41	localparam S_WRITE = 3'd3;
42	localparam S_NEXT  = 3'd4;
43	localparam S_DONE  = 3'd5;
44	
45	wire [31:0] a_idx = m * K_in + k[DIM_W-1:0];
46	wire [31:0] b_idx = k[DIM_W-1:0] * N_in + n;
47	wire [31:0] c_idx = m * N_in + n;
48	
49	wire signed [15:0] prod16 = $signed(a_buf[a_idx[15:0]])
50	                          * $signed(b_buf[b_idx[15:0]]);
51	wire signed [31:0] prod32 = {{16{prod16[15]}}, prod16};
52	
53	integer kk;
54	always @(posedge clk or negedge rst_n) begin
55	    if (!rst_n) begin
56	        state <= S_IDLE;
57	        done  <= 1'b0;
58	        m <= 0; n <= 0; k <= 0;
59	        acc <= 0;
60	        for (kk = 0; kk < C_LEN; kk = kk + 1) c_buf[kk] <= 0;
61	    end else begin
62	        done <= 1'b0;
63	        case (state)
64	            S_IDLE: begin
65	                if (start) begin
66	                    m <= 0; n <= 0; k <= 0;
67	                    state <= S_INIT;
68	                end
69	            end
70	            S_INIT: begin
71	                acc   <= use_bias ? bias_buf[m] : 32'sd0;
72	                k     <= 0;
73	                state <= S_MAC;
74	            end
75	            S_MAC: begin
76	                if (k < {1'b0, K_in}) begin
77	                    acc <= acc + prod32;
78	                    k   <= k + 1;
79	                end else begin
80	                    state <= S_WRITE;
81	                end
82	            end
83	            S_WRITE: begin
84	                c_buf[c_idx[DIM_W:0]] <= acc;
85	                state <= S_NEXT;
86	            end
87	            S_NEXT: begin
88	                if (n + 1 < N_in) begin
89	                    n <= n + 1;
90	                    state <= S_INIT;
91	                end else begin
92	                    n <= 0;
93	                    if (m + 1 < M_in) begin
94	                        m <= m + 1;
95	                        state <= S_INIT;
96	                    end else begin
97	                        state <= S_DONE;
98	                    end
99	                end
100	            end
101	            S_DONE: begin
102	                done  <= 1'b1;
103	                state <= S_IDLE;
104	            end
105	            default: state <= S_IDLE;
106	        endcase
107	    end
108	end
109	
110	endmodule
